package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionShapeScaleTest {
 @Test public void entireDomainBothFormsShapesAndExactFractionalAmounts(){assertEquals(43,FractionShapeScale.FACTORS.size());assertEquals(12642,FractionShapeScale.domainSize());Set<String> seen=new HashSet<>();Set<Integer> shapes=new HashSet<>();boolean shrink=false,enlarge=false,identity=false,nonintegerAnswer=false;for(int i=0;i<FractionShapeScale.domainSize();i++){Question q=FractionShapeScale.at(i);var v=FractionShapeScale.read(q);assertNotNull(v);shapes.add(v.shape());assertTrue(seen.add(q.signature()));Rational factor=v.known()?v.other():v.other().div(v.first()),answer=v.known()?v.first().mul(v.other()):factor;shrink|=factor.compareTo(Rational.ONE)<0;enlarge|=factor.compareTo(Rational.ONE)>0;identity|=factor.equals(Rational.ONE);nonintegerAnswer|=!answer.isInteger();assertTrue(new Checker().check(q,List.of(),List.of(answer.toString())).correct());assertEquals(v.first().toString(),q.diagram.labels[0]);assertEquals(v.known()?"?":v.other().toString(),q.diagram.labels[1]);if(!answer.isInteger()){assertEquals("fraction",q.answerFormat);assertTrue(FractionInput.defaultFraction(q));}q.answers=new String[]{"999999"};q.expression="poison";HelpPlan h=HelpPlan.forQuestion(q);assertEquals(3,h.size());assertFalse(h.canTransfer());List<String> frames=List.of(v.first().toString(),v.other().toString(),answer.toString());for(int j=0;j<3;j++){assertTrue(h.step(j).accepts(frames.get(j)));assertFalse(h.step(j).accepts("999999"));assertEquals("",h.step(j).after);}}assertEquals(Set.of(0,1,2),shapes);assertTrue(shrink&&enlarge&&identity&&nonintegerAnswer);}
 @Test public void selectedCombinedSupplyIsFreshAndCoversFractionReductionAndAllShapes(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();List<String> recent=new ArrayList<>();Generator g=new Generator(new Random(101));Set<Integer> shapes=new HashSet<>();Set<Boolean> modes=new HashSet<>();boolean fractionalShrink=false;for(int i=0;i<200;i++){Question q=g.next(SimilarShapeSupply.ID,recent,false,GlobalCurriculum.limits(pack.id,SimilarShapeSupply.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=FractionShapeScale.read(q);if(v!=null){shapes.add(v.shape());modes.add(v.known());Rational factor=v.known()?v.other():v.other().div(v.first());fractionalShrink|=!factor.isInteger()&&factor.compareTo(Rational.ONE)<0;}}assertEquals(Set.of(0,1,2),shapes);assertEquals(Set.of(false,true),modes);assertTrue(fractionalShrink);}
 @Test public void existingDraftRetainsOldGuideAndNoDivisionByZero(){Question q=SimilarShapeSupply.at(1);HelpPlan h=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.teachingVersion=q.studyGuide.teachingVersion;d.stage=1;d.entries=new ArrayList<>(List.of("2","",""));h.restore(d,q.id);assertEquals(1,d.stage);assertEquals("similar-shape-scale-v1",q.studyGuide.teachingVersion);assertNull(FractionShapeScale.read(new Question(SimilarShapeSupply.ID,"두 닮은 삼각형에서 첫째 대응변은 0, 둘째 대응변은 2입니다. 첫째에서 둘째로의 배율은?","","")));}
}
